
/* ============================================================
   ARIBA V88 — إضافة فقط: تقرير حضور وانصراف قابل للطباعة بفترة
   زمنية محددة، لكل الموظفين أو موظف واحد، بنفس الورق الرسمي
   لأريبا، مع ملخص إحصائي واضح لكل موظف (أيام الحضور، التأخير،
   الانصراف المبكر، إجمالي ساعات العمل).
   ============================================================ */
(function(){
  'use strict';
  var CLOUD_URL = 'https://iwviydmapqpqihcdazpe.supabase.co';
  var CLOUD_KEY = 'sb_publishable_5PsFLEVv6w3Cxo1-WqWwdg_cYlNfLfB';
  var HEADER_IMG_88 = 'data:image/jpeg;base64,';
  var FOOTER_IMG_88 = 'data:image/jpeg;base64,';

  var DAY_NAMES_AR = ['الأحد','الإثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'];

  function esc88(s){ return String(s==null?'':s).replace(/[&<>"']/g, function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];}); }
  function fD88(v){ if(!v) return '—'; try{ var d=new Date(v); return d.toLocaleDateString('ar-SA-u-ca-gregory-nu-latn'); }catch(e){ return v; } }
  function dayName88(v){ try{ return DAY_NAMES_AR[new Date(v).getDay()]; }catch(e){ return ''; } }
  function fTime88(t){ if(!t) return '—'; return String(t).slice(0,5); }
  function fHours88(h){ return (Number(h)||0).toFixed(2); }

  async function cloudRpc88(fn, args){
    if(!window.ARIBA_HR_TOKEN || window.ARIBA_HR_TOKEN === 'local_admin_token'){
      throw new Error('محتاج تسجيل دخول سحابي حقيقي عشان تقدر تطبع التقرير');
    }
    var r = await fetch(CLOUD_URL+'/rest/v1/rpc/'+fn, {
      method:'POST',
      headers:{apikey:CLOUD_KEY, Authorization:'Bearer '+CLOUD_KEY, 'Content-Type':'application/json', 'Prefer':'return=representation'},
      body: JSON.stringify(Object.assign({p_token: window.ARIBA_HR_TOKEN}, args||{}))
    });
    var t = await r.text(), d = null;
    try{ d = t ? JSON.parse(t) : null; }catch(ex){}
    if(!r.ok) throw new Error((d && (d.message||d.hint||d.error)) || 'تعذر الاتصال');
    return d;
  }

  var REPORT_CSS_88 =
    '<style>'+
    '@page{size:A4;margin:0}'+
    '*{box-sizing:border-box}'+
    'body{font-family:"ARIBA Two","Segoe UI",Tahoma,Arial,sans-serif;color:#14231d;margin:0;font-size:11px}'+
    '.doc{width:100%;max-width:210mm;margin:0 auto;position:relative;padding:0 14mm}'+
    '.lh-head{width:calc(100% + 28mm);display:block;margin:0 -14mm 6mm -14mm;max-width:none}'+
    '.lh-foot{width:100%;display:block;position:fixed;bottom:0;left:0}'+
    '.doc-body{padding-bottom:14mm}'+
    '.rp-title{text-align:center;font-size:17px;font-weight:900;color:#014D3D;margin-bottom:2mm}'+
    '.rp-sub{text-align:center;font-size:11.5px;color:#555;margin-bottom:5mm}'+
    '.rp-summary{display:grid;grid-template-columns:repeat(5,1fr);gap:6px;margin-bottom:6mm}'+
    '.rp-sbox{background:#eef5f2;border:1px solid #d8e2de;border-radius:8px;padding:8px 6px;text-align:center}'+
    '.rp-sbox .v{font-size:16px;font-weight:900;color:#014D3D}'+
    '.rp-sbox .l{font-size:9.5px;color:#666;margin-top:2px}'+
    'table.rp-tb{width:100%;border-collapse:collapse;margin-bottom:5mm;font-size:10px;page-break-inside:auto}'+
    'table.rp-tb th{background:#014D3D;color:#fff;padding:5px 6px;font-size:9.5px;text-align:center}'+
    'table.rp-tb td{padding:4px 6px;border-bottom:1px solid #e5ece9;text-align:center}'+
    'table.rp-tb tr{page-break-inside:avoid}'+
    'table.rp-tb tr:nth-child(even){background:#f8faf9}'+
    '.rp-badge{display:inline-block;padding:1.5px 7px;border-radius:9px;font-size:8.5px;font-weight:700}'+
    '.rp-g{background:#e6f6ec;color:#0a7a3f}.rp-r{background:#fbe9e9;color:#c0392b}.rp-a{background:#fff4e0;color:#a15c00}.rp-k{background:#f0f0f0;color:#888}'+
    '.rp-emp-hd{background:#014D3D;color:#fff;padding:6px 10px;border-radius:6px;font-size:12px;font-weight:800;margin:6mm 0 2mm;page-break-after:avoid}'+
    '.rp-emp-hd:first-of-type{margin-top:0}'+
    '.rp-ft{margin-top:8mm;padding-top:4mm;border-top:1px solid #ddd;font-size:8.5px;color:#999;text-align:center}'+
    '</style>';

  function statusBadge88(status, late, early){
    if(status==='late') return '<span class="rp-badge rp-a">متأخر '+late+' د</span>';
    if(early>0) return '<span class="rp-badge rp-a">مبكر '+early+' د</span>';
    if(status==='present') return '<span class="rp-badge rp-g">حاضر</span>';
    return '<span class="rp-badge rp-k">'+esc88(status||'—')+'</span>';
  }

  function buildEmployeeSection(emp, records, fromDate, toDate){
    // تجميع السجلات حسب اليوم (لو فيه أكتر من بصمة في نفس اليوم)
    var byDate = {};
    records.forEach(function(r){
      if(!byDate[r.date]) byDate[r.date] = { date:r.date, timeIn:r.time_in, timeOut:r.time_out, status:r.status, late:r.late_minutes, early:r.early_minutes, hours:r.hours, sessions:1 };
      else {
        var g = byDate[r.date];
        g.sessions += 1;
        if(r.time_in && r.time_in < g.timeIn) g.timeIn = r.time_in;
        if(r.time_out===null || (g.timeOut && r.time_out>g.timeOut)) g.timeOut = r.time_out;
        g.hours = Math.round((g.hours + r.hours)*100)/100;
        if(r.status==='late') g.status='late';
      }
    });
    var days = Object.values(byDate).sort(function(a,b){ return a.date < b.date ? -1 : 1; });
    var totalPresent = days.length;
    var totalLate = days.reduce(function(s,d){ return s + (d.late||0); }, 0);
    var totalEarly = days.reduce(function(s,d){ return s + (d.early||0); }, 0);
    var totalHours = days.reduce(function(s,d){ return s + (d.hours||0); }, 0);
    var lateDays = days.filter(function(d){ return d.late>0; }).length;

    var rows = days.map(function(d){
      return '<tr><td>'+fD88(d.date)+'</td><td>'+dayName88(d.date)+'</td><td>'+fTime88(d.timeIn)+'</td><td>'+fTime88(d.timeOut)+'</td>'+
        '<td>'+fHours88(d.hours)+(d.sessions>1?' <span style="color:#999">(×'+d.sessions+')</span>':'')+'</td>'+
        '<td>'+statusBadge88(d.status, d.late, d.early)+'</td></tr>';
    }).join('');

    return '<div class="rp-emp-hd">'+esc88(emp.nameAr||emp.name||emp.id)+' — '+esc88(emp.jobTitle||'')+' ('+esc88(emp.empNo||emp.id)+')</div>'+
      '<div class="rp-summary">'+
        '<div class="rp-sbox"><div class="v">'+totalPresent+'</div><div class="l">أيام حضور</div></div>'+
        '<div class="rp-sbox"><div class="v">'+lateDays+'</div><div class="l">أيام تأخير</div></div>'+
        '<div class="rp-sbox"><div class="v">'+totalLate+'</div><div class="l">إجمالي دقائق التأخير</div></div>'+
        '<div class="rp-sbox"><div class="v">'+totalEarly+'</div><div class="l">إجمالي دقائق الانصراف المبكر</div></div>'+
        '<div class="rp-sbox"><div class="v">'+fHours88(totalHours)+'</div><div class="l">إجمالي ساعات العمل</div></div>'+
      '</div>'+
      (rows ? '<table class="rp-tb"><tr><th>التاريخ</th><th>اليوم</th><th>الحضور</th><th>الانصراف</th><th>الساعات</th><th>الحالة</th></tr>'+rows+'</table>'
            : '<div style="text-align:center;color:#999;padding:10px 0 6mm">لا توجد بصمات حضور في هذه الفترة</div>');
  }

  function buildAllEmployeesSummary(list, recordsByEmp, fromDate, toDate){
    var rows = list.map(function(e){
      var recs = recordsByEmp[String(e.id)] || [];
      var byDate = {};
      recs.forEach(function(r){ byDate[r.date] = byDate[r.date] || {late:0,early:0,hours:0}; var g=byDate[r.date]; if(r.status==='late') g.late = Math.max(g.late, r.late_minutes||0); g.early += (r.early_minutes||0); g.hours += (r.hours||0); });
      var present = Object.keys(byDate).length;
      var lateDays = Object.values(byDate).filter(function(d){ return d.late>0; }).length;
      var totalHours = Object.values(byDate).reduce(function(s,d){ return s+d.hours; },0);
      return '<tr><td>'+esc88(e.empNo||e.id)+'</td><td style="text-align:right;font-weight:600">'+esc88(e.nameAr||e.name)+'</td><td>'+present+'</td><td>'+lateDays+'</td><td>'+fHours88(totalHours)+'</td></tr>';
    }).join('');
    return '<table class="rp-tb"><tr><th>الرقم</th><th>الموظف</th><th>أيام حضور</th><th>أيام تأخير</th><th>إجمالي الساعات</th></tr>'+rows+'</table>';
  }

  window.aribaPrintAttendanceReport = async function(){
    var fromEl = document.getElementById('V88_FROM');
    var toEl = document.getElementById('V88_TO');
    var empEl = document.getElementById('V88_EMP');
    if(!fromEl || !fromEl.value || !toEl || !toEl.value){
      if(typeof toast==='function') toast('حدد الفترة من وإلى أولاً', 'ter');
      return;
    }
    var fromDate = fromEl.value, toDate = toEl.value;
    var empId = empEl ? empEl.value : '';

    try{
      if(typeof toast==='function') toast('جاري تجهيز التقرير...', 'tin');
      var records = await cloudRpc88('ariba_hr_attendance_range', {p_from: fromDate, p_to: toDate, p_employee_id: empId || null});
      var allEmps = (typeof window.aEmps === 'function') ? window.aEmps() : [];
      var byEmpNo = {}; allEmps.forEach(function(e){ if(e.empNo!=null) byEmpNo[String(e.empNo)] = e; byEmpNo[String(e.id)] = e; });

      var recordsByEmp = {};
      records.forEach(function(r){
        var localEmp = byEmpNo[String(r.emp_id)];
        var key = localEmp ? String(localEmp.id) : String(r.emp_id);
        recordsByEmp[key] = recordsByEmp[key] || [];
        recordsByEmp[key].push(r);
      });

      var html, title;
      if(empId){
        var emp = allEmps.find(function(e){ return String(e.id)===String(empId); });
        if(!emp){ if(typeof toast==='function') toast('تعذر إيجاد بيانات الموظف محليًا', 'ter'); return; }
        title = 'تقرير حضور — ' + (emp.nameAr||emp.name);
        html = REPORT_CSS_88 +
          '<div class="doc"><img class="lh-head" src="'+HEADER_IMG_88+'"><div class="doc-body">'+
          '<div class="rp-title">تقرير الحضور والانصراف</div>'+
          '<div class="rp-sub">من '+fD88(fromDate)+' إلى '+fD88(toDate)+'</div>'+
          buildEmployeeSection(emp, recordsByEmp[String(emp.id)] || [], fromDate, toDate)+
          '<div class="rp-ft">تقرير آلي من نظام الموارد البشرية — أريبا</div>'+
          '</div><img class="lh-foot" src="'+FOOTER_IMG_88+'"></div>';
      } else {
        title = 'تقرير الحضور الشامل';
        html = REPORT_CSS_88 +
          '<div class="doc"><img class="lh-head" src="'+HEADER_IMG_88+'"><div class="doc-body">'+
          '<div class="rp-title">تقرير الحضور والانصراف — كل الموظفين</div>'+
          '<div class="rp-sub">من '+fD88(fromDate)+' إلى '+fD88(toDate)+'</div>'+
          buildAllEmployeesSummary(allEmps, recordsByEmp, fromDate, toDate)+
          '<div class="rp-ft">تقرير آلي من نظام الموارد البشرية — أريبا</div>'+
          '</div><img class="lh-foot" src="'+FOOTER_IMG_88+'"></div>';
      }

      if(typeof window.printHtml === 'function') window.printHtml(title, html);
    }catch(err){
      if(typeof toast==='function') toast('⚠️ '+(err.message||'تعذر إنشاء التقرير'), 'ter');
    }
  };

  function buildCard88(){
    var card = document.createElement('div');
    card.className = 'card';
    card.id = 'V88_REPORT_CARD';
    card.style.cssText = 'padding:12px;margin-top:12px';
    card.innerHTML =
      '<div class="ct" style="margin-bottom:8px"><i class="ti ti-printer"></i> طباعة تقرير الحضور</div>'+
      '<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-end">'+
        '<div><label style="font-size:10px;color:var(--mu);display:block;margin-bottom:2px">من تاريخ</label><input type="date" id="V88_FROM" style="width:150px"></div>'+
        '<div><label style="font-size:10px;color:var(--mu);display:block;margin-bottom:2px">إلى تاريخ</label><input type="date" id="V88_TO" style="width:150px"></div>'+
        '<div style="flex:1;min-width:200px"><label style="font-size:10px;color:var(--mu);display:block;margin-bottom:2px">الموظف</label>'+
          '<select id="V88_EMP" style="width:100%"><option value="">— كل الموظفين —</option></select></div>'+
        '<button class="btn bsm" style="background:#014D3D;color:#fff" onclick="aribaPrintAttendanceReport()"><i class="ti ti-printer"></i> طباعة التقرير</button>'+
      '</div>';
    return card;
  }

  function ensureCard88(){
    try{
      var page = document.getElementById('pg-att');
      if(page && !document.getElementById('V88_REPORT_CARD')){
        page.appendChild(buildCard88());
        var today = new Date();
        var first = new Date(today.getFullYear(), today.getMonth(), 1);
        document.getElementById('V88_FROM').value = first.toISOString().slice(0,10);
        document.getElementById('V88_TO').value = today.toISOString().slice(0,10);
      }
      var sel = document.getElementById('V88_EMP');
      if(sel && typeof window.aEmps === 'function'){
        var cur = sel.value;
        var list = window.aEmps();
        if(sel.options.length - 1 !== list.length){
          sel.innerHTML = '<option value="">— كل الموظفين —</option>' + list.map(function(e){
            return '<option value="'+e.id+'">'+esc88(e.nameAr||e.name||e.id)+'</option>';
          }).join('');
          if(cur) sel.value = cur;
        }
      }
    }catch(e){}
  }
  setInterval(ensureCard88, 1500);
})();
